'use strict';

const extName = 'ABCJS';
const codeName = 'abc'

if (typeof window === 'undefined') {
  throw Error('The showdown abcjs extension can only be used in browser environment!');
}

import format from './log';
import cdnjs from './cdn';
import utils from './utils';

if (typeof ABCJS === 'undefined') {
  var ABCJS = window.ABCJS || undefined;
}

function hasAbc() {
  return !!ABCJS;
}

let dync = false;
function dyncLoadScript() {
  const sync = hasAbc();
  if (typeof window !== 'undefined') {
    if (dync) {
      return sync;
    }

    if (!sync) {
      dync = true;
      utils.loadStyle(
        'abc-audio',
        '.highlight{fill: #0a9ecc;} .abcjs-cursor{stroke: red;}' +
          ' .abcjs-inline-audio .abcjs-midi-loop.abcjs-pushed{border: none;}' +
          ' .abcjs-inline-audio .abcjs-midi-loop.abcjs-pushed svg path{fill: #6eaa49;}'
      );
      cdnjs.loadScript(extName).then((name) => {
        ABCJS = utils.interopDefault(window[name]);
      }).catch((err) =>{
        console.log('load abcjs failed: ' + err);
      });
    }
  }
  return sync;
}

function unloadScript() {
  if (!hasAbc()) return;
  cdnjs.unloadScript('ABCJS');
  ABCJS = null;
  window.ABCJS = null;
  dync = false;
}

function abcCreateEnv() {
  if (typeof ABCJS === 'undefined') {
    var ABCJS = window.ABCJS || undefined;
  }

  function cursorControl(id) {
    const self = this;
    self.onReady = function () {};
    self.onStart = function () {
      const tag = '#' + id + ' svg';
      const svg = document.querySelector(tag);
      const cursor = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      cursor.setAttribute('class', 'abcjs-cursor');
      cursor.setAttributeNS(null, 'x1', 0);
      cursor.setAttributeNS(null, 'y1', 0);
      cursor.setAttributeNS(null, 'x2', 0);
      cursor.setAttributeNS(null, 'y2', 0);
      svg.appendChild(cursor);
    };
    self.beatSubdivisions = 2;
    self.onBeat = function (beatNumber, totalBeats, totalTime) {};
    self.onEvent = function (ev) {
      if (ev.measureStart && ev.left === null) return; // this was the second part of a tie across a measure line. Just ignore it.

      const className = '#' + id + ' svg .highlight';
      const lastSelection = document.querySelectorAll(className);
      for (let k = 0; k < lastSelection.length; k++) lastSelection[k].classList.remove('highlight');

      for (let i = 0; i < ev.elements.length; i++) {
        const note = ev.elements[i];
        for (let j = 0; j < note.length; j++) {
          note[j].classList.add('highlight');
        }
      }

      const tag = '#' + id + ' svg .abcjs-cursor';
      const cursor = document.querySelector(tag);
      if (cursor) {
        cursor.setAttribute('x1', ev.left - 2);
        cursor.setAttribute('x2', ev.left - 2);
        cursor.setAttribute('y1', ev.top);
        cursor.setAttribute('y2', ev.top + ev.height);
      }
    };
    self.onFinished = function () {
      const className = '#' + id + ' svg .highlight';
      const els = document.querySelectorAll(className);
      for (let i = 0; i < els.length; i++) {
        els[i].classList.remove('highlight');
      }
      const tag = '#' + id + ' svg .abcjs-cursor';
      const cursor = document.querySelector(tag);
      if (cursor) {
        cursor.setAttribute('x1', 0);
        cursor.setAttribute('x2', 0);
        cursor.setAttribute('y1', 0);
        cursor.setAttribute('y2', 0);
      }
    };
  }

  window.abcEnv = {
    abcOptions: {
      add_classes: true,
      responsive: 'resize',
    },
    setTune(render, userAction, synthControl) {
      const id = render.id;
      const abc = render.data;
      if (!synthControl) {
        ABCJS.renderAbc(id, abc, this.abcOptions);
        return;
      }

      synthControl.disable(true);
      const visualObj = ABCJS.renderAbc(id, abc, this.abcOptions)[0];
      const midiBuffer = new ABCJS.synth.CreateSynth();
      midiBuffer
        .init({
          visualObj: visualObj,
        })
        .then(function (response) {
          synthControl
            .setTune(visualObj, userAction)
            .then(function (response) {
              console.log('Audio successfully loaded.');
            })
            .catch(function (error) {
              console.warn('Audio problem:', error);
            });
        })
        .catch(function (error) {
          console.warn('Audio problem:', error);
        });
    },
    load(audio, render) {
      let synthControl;
      if (audio) {
        const id = '#' + audio;
        if (ABCJS.synth.supportsAudio()) {
          synthControl = new ABCJS.synth.SynthController();
          synthControl.load(id, new cursorControl(render.id), {
            displayLoop: true,
            displayRestart: true,
            displayPlay: true,
            displayProgress: true,
            displayWarp: true,
          });
        } else {
          document.querySelector(id).innerHTML =
            "<div class='audio-error'>Audio is not supported in this browser.</div>";
        }
      }
      this.setTune(render, false, synthControl);
    },
  };
}

function loadABC(audio, render) {
  const result = function () {
    window.abcEnv.load(audio, render);
  };

  result.toString = function () {
    return `function(){
      const audio = '${audio}';
      const render = ${JSON.stringify(render)};
      window.abcEnv.load(audio, render);
    }`;
  };

  return result;
}

function onRenderAbc(resolve, scripts, meta) {
  if (hasAbc()) {
    const id = meta.id;
    const name = meta.className;
    const container = meta.container;
    let style = '';
    if (meta.lang) {
      if (meta.lang.width) {
        style += `width:${meta.lang.width};`;
      }
      if (meta.lang.height) {
        style += `height:${meta.lang.height};`;
      }
    }
    let html = '';
    if (style) {
      html += `<div id="${container}" class="${name}" style="${style}">`;
      html += `<div id="${id}" style="width:100%;height:100%;display:inline-block"></div>`;
    } else {
      html += `<div id="${container}" class="${name}">`;
      html += `<div id="${id}"></div>`;
    }
    if (!meta.lang || !meta.lang.audio) {
      const data = meta.data;
      const doc = meta.element.ownerDocument;
      html += '</div>';
      meta.element.parentNode.outerHTML = html;
      const element = doc.getElementById(id);
      ABCJS.renderAbc(element, data, {
        add_classes: true,
        responsive: 'resize',
      });
      return resolve(true);
    }

    const data = meta.data;
    const audio = id + '-audio';
    if (style) {
      html += `<div id="${audio}" style="width:100%;height:100%;display:inline-block"></div>`;
    } else {
      html += `<div id="${audio}"></div>`;
    }
    html += '</div>';
    meta.element.parentNode.outerHTML = html;

    const script = {
      id: container,
      code: loadABC(audio, {
        id: id,
        class: name,
        data: data,
      }),
      host: `#${container}`,
    };
    scripts.push(script);
    return resolve(true);
  }

  setTimeout(() => {
    onRenderAbc(resolve, scripts, meta);
  }, 10);
}

/**
 * render abc graphs
 */
function renderAbc(element, scripts) {
  return new Promise((resolve) => {
    let meta = utils.createElementMeta(codeName, element);
    if (!meta || !meta.data) {
      return resolve(false);
    }

    onRenderAbc(resolve, scripts, meta);
  });
}

// <div class="abc"></div>
function renderAbcElements(elements, scripts) {
  const script = {
    outer: [
      {
        name: 'ABCJS',
        src: cdnjs.getSrc(false, 'ABCJS', 'jsdelivr'),
      },
    ],
    id: 'abcjs-ext',
    code: abcCreateEnv,
    inner: [],
  };
  scripts.push(script);
  dyncLoadScript();
  return new Promise((resolve) => {
    const promiseArray = [];
    elements.forEach((element) => {
      promiseArray.push(renderAbc(element, script.inner));
    });
    Promise.all(promiseArray).then(() => {
      resolve(true);
    });
  });
}

function showdownAbc() {
  return [
    {
      type: 'output',
      filter: function (obj) {
        const wrapper = obj.wrapper;
        if (!wrapper) {
          return false;
        }

        // find the abc in code blocks
        const elements = wrapper.querySelectorAll(`code.${codeName}.language-${codeName}`);
        if (!elements.length) {
          return false;
        }

        this.config = {
          cssLink: cdnjs.getCSS(true, extName),
        };
        utils.addCssLink(obj, this.config.cssLink, 'css-abc');
        console.log(format(`Begin render ${extName} elements.`));
        return renderAbcElements(elements, obj.scripts).then(() => {
          console.log(format(`End render ${extName} elements.`));
          return obj;
        });
      },
    },
  ];
}

export default showdownAbc;
